import{_ as e,H as s,f as a,i as o}from"./chunks/framework.CSxcEb-0.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),n={name:"getting-started.md"};function r(i,t,l,g,d,h){return s(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>This tutorial walks you through TemPad in about five minutes. Each step matches labels in the live app at <a href="https://jaredescott.github.io/tempad/" target="_blank" rel="noreferrer">jaredescott.github.io/tempad</a>.</p><h2 id="step-1" tabindex="-1">Step 1 — Open TemPad and sign in <a class="header-anchor" href="#step-1" aria-label="Permalink to &quot;Step 1 — Open TemPad and sign in {#step-1}&quot;">​</a></h2><p><strong>What to click:</strong> Open the app, then <strong>Sign in with Google</strong> or <strong>Continue without sign-in</strong>.</p><p><strong>What you should see:</strong> The main shell with sidebar (Calendar, Tasks, Routines, Notepad, Settings).</p><p><strong>Common mistake:</strong> Expecting cloud sync in local-only mode — that data stays in this browser only.</p><p>→ <a href="./guide/settings.html">Settings guide</a> · <a href="./troubleshooting.html">Troubleshooting</a></p><h2 id="step-2" tabindex="-1">Step 2 — Confirm Settings basics <a class="header-anchor" href="#step-2" aria-label="Permalink to &quot;Step 2 — Confirm Settings basics {#step-2}&quot;">​</a></h2><p><strong>What to click:</strong> <strong>Settings</strong> in the sidebar. Review scheduling hours, default list, and scheduler options.</p><p><strong>What you should see:</strong></p><ul><li>At least one <strong>scheduling hours</strong> profile (e.g. Work hours, Personal hours)</li><li>A <strong>default list</strong> for new tasks</li><li>Optional: <strong>Schedule breaks</strong> and scheduling horizon under Scheduler</li></ul><p><strong>Common mistake:</strong> Leaving all days disabled on a profile — the scheduler has nowhere to place tasks.</p><p>→ <a href="./guide/settings.html">Settings guide</a></p><h2 id="step-3" tabindex="-1">Step 3 — Add tasks <a class="header-anchor" href="#step-3" aria-label="Permalink to &quot;Step 3 — Add tasks {#step-3}&quot;">​</a></h2><p><strong>What to click:</strong> <strong>Tasks</strong> → add tasks with title, list, <strong>due date</strong>, and <strong>duration</strong>.</p><p><strong>What you should see:</strong> New tasks in the list (and inbox if applicable). Enable priorities in Settings if you want ASAP/High/Normal/Low.</p><p><strong>Common mistake:</strong> Adding tasks without due dates or duration — auto-schedule needs both to place work.</p><p>→ <a href="./guide/tasks.html">Tasks guide</a></p><h2 id="step-4" tabindex="-1">Step 4 — Connect Google Calendar (optional) <a class="header-anchor" href="#step-4" aria-label="Permalink to &quot;Step 4 — Connect Google Calendar (optional) {#step-4}&quot;">​</a></h2><p><strong>What to click:</strong> <strong>Settings</strong> → <strong>Google Calendar sync</strong> → <strong>Connect calendars</strong>. Approve access, then enable the calendars you want.</p><p><strong>What you should see:</strong> Google events appear as busy blocks on the calendar after sync. Requires Google sign-in (not local-only).</p><p><strong>Common mistake:</strong> Enabling the Calendar API in Google Cloud but not reconnecting in TemPad after a 403 error.</p><p>→ <a href="./guide/google-calendar.html">Google Calendar guide</a></p><h2 id="step-5" tabindex="-1">Step 5 — Reschedule on the calendar <a class="header-anchor" href="#step-5" aria-label="Permalink to &quot;Step 5 — Reschedule on the calendar {#step-5}&quot;">​</a></h2><p><strong>What to click:</strong> <strong>Calendar</strong> → <strong>Reschedule</strong> (toolbar refresh).</p><p><strong>What you should see:</strong> Tasks placed into free slots inside your scheduling hours, avoiding events and other blocks.</p><p><strong>Common mistake:</strong> Expecting instant updates while editing — run <strong>Reschedule</strong> after bulk changes, or rely on auto-schedule triggers after saves.</p><p>→ <a href="./guide/calendar.html">Calendar guide</a></p><h2 id="step-6" tabindex="-1">Step 6 — Drag and lock (optional) <a class="header-anchor" href="#step-6" aria-label="Permalink to &quot;Step 6 — Drag and lock (optional) {#step-6}&quot;">​</a></h2><p><strong>What to click:</strong> Drag a task block to a new time on the week view.</p><p><strong>What you should see:</strong> The block moves and shows a dashed outline (locked). Press <strong>Reschedule</strong> again to unlock all tasks and recalculate.</p><p><strong>Common mistake:</strong> Thinking drag permanently overrides dependencies — <strong>Reschedule</strong> still respects dependency order when recalculating.</p><p>→ <a href="./guide/calendar.html">Calendar guide</a></p><h2 id="step-7" tabindex="-1">Step 7 — Explore task views <a class="header-anchor" href="#step-7" aria-label="Permalink to &quot;Step 7 — Explore task views {#step-7}&quot;">​</a></h2><p><strong>What to click:</strong> <strong>Tasks</strong> and switch <strong>List</strong>, <strong>Kanban</strong>, or <strong>Eisenhower</strong>. Use sidebar list chips to filter.</p><p><strong>What you should see:</strong> The same tasks in different layouts; Kanban columns follow your lists.</p><p><strong>Common mistake:</strong> Forgetting list filters — a hidden list can make tasks seem “missing.”</p><p>→ <a href="./guide/tasks.html">Tasks guide</a></p><h2 id="step-8" tabindex="-1">Step 8 — Routines, Notepad, list colors (optional) <a class="header-anchor" href="#step-8" aria-label="Permalink to &quot;Step 8 — Routines, Notepad, list colors (optional) {#step-8}&quot;">​</a></h2><p><strong>What to click:</strong></p><ul><li><strong>Routines</strong> for recurring protected time</li><li><strong>Notepad</strong> for planning notes (toggle multi-page mode in Settings if needed)</li><li><strong>Settings → Lists</strong> for list colors and cross-theme consistency</li></ul><p><strong>What you should see:</strong> Routines on their own view; notepad content saved with your app state; colored list indicators across calendar and tasks.</p><p>→ <a href="./guide/routines.html">Routines</a> · <a href="./guide/notepad.html">Notepad</a> · <a href="./guide/settings.html">Settings</a></p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Read the full <a href="./guide/calendar.html">Guide</a> sections for depth</li><li>Use <a href="./troubleshooting.html">Troubleshooting</a> if Google sync or sign-in fails</li><li>In the app: <strong>Settings</strong> shows a checklist that links back to these steps</li></ul>',45)])])}const c=e(n,[["render",r]]);export{u as __pageData,c as default};
